#!/bin/bash
#
# SLURM queue script generated by mcsub

#SBATCH --job-name=McStas_gr1_%j
#SBATCH --error=TestSuite_gr1_%j.err
#SBATCH --output=TestSuite_gr1_%j.out
#SBATCH --nodes 1
#SBATCH --partition=mesonet
##SBATCH --gres=gpu:1
#SBATCH --ntasks=1
#SBATCH -c 56
#SBATCH --time 12:00:00
#SBATCH --account m26216

export DATE=`date +%F`

export MAMBA_EXE='/projects/m26216/INSTALL/bin/micromamba';
export MAMBA_ROOT_PREFIX='/projects/m26216/INSTALL/micromamba/';
eval "$("$MAMBA_EXE" shell hook --shell bash --root-prefix "$MAMBA_ROOT_PREFIX" 2> /dev/null)"
micromamba activate panraid
spack load cuda@12.6.2
spack load nvhpc@25.7

# Run all instruments in ${MCSTAS} that match filename PSI
#mctest --ncount=1e7 --verbose --openacc --compilemax=1200 --runmax=600 --instr=PSI

# You could also run a single instrument via mcrun, i.e. for GPU:
#mcrun -c --openacc PSI_Focus_part1_to_sample.instr -n1e5 -d part1_small -y 


# Same using CPU/mpi
mcrun -c --mpi=auto PSI_Focus_part2_from_sample.instr no_incoh=0 temp=100,300 theta=0,-10 radius=0.01,0.03 -n1e8 -d with_inco -M -N 30
#mcrun -c --mpi=auto PSI_Focus_part1_to_sample.instr -n1e10 -d part1_big 

# Use 'auto' to use whatever is reserved via slurm ('ntasks')
# mcrun -c --mpi=auto My_instrument.instr par1=1 -n1e8 -d output3

echo $SECONDS
### END of McSub script


